@startuml

class Ingredient {
  + name : string
  + measuring_unit : string
  + quantity_in_stock : float
}

class Dish {
  + name : string
  + id : int
}

class IngredientUsage {
  + quantity : float
}

class Table {
  + id : int
  + max_people : int
}

class Meal {
  + date : date
  + start_time : time
  + end_time : time
}

class Waiter {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class Client {
  + tax_identification_number : string
  + name : string
  + address : string
}

Meal "1" -- "0..1" Client : consumed by
Meal "1" -- "1" Waiter : responsible waiter
Meal "1" -- "1..*" Table : takes place at
Meal "1" -- "1..*" Dish : includes

Dish "1" -- "1..*" Ingredient : composed of
Dish "1" -- "1..*" IngredientUsage : contains
IngredientUsage "1" -- "1" Ingredient : uses

@enduml

